create table if not exists public.billing_events (id uuid primary key default gen_random_uuid(), provider text not null, provider_event_id text not null unique, organization_id uuid references public.organizations(id) on delete set null, event_type text not null, payload jsonb not null default '{}'::jsonb, received_at timestamptz not null default now(), processed_at timestamptz, status text not null default 'RECEIVED' check (status in ('RECEIVED','PROCESSED','FAILED')), error text);